import mongoose from 'mongoose';
import { COMPANY_STATUS } from '../constants/index.js';
import { jsonOptions } from './shared/json.js';
import { searchable } from './shared/searchable.js';

const { ObjectId } = mongoose.Schema.Types;

const companySchema = new mongoose.Schema(
  {
    // Generated by the server (see services/sequence.service.js); never accepted from clients.
    companyCode: { type: String, required: true, unique: true, immutable: true },
    name: { type: String, required: true, trim: true, maxlength: 200, index: true },
    legalName: { type: String, trim: true, maxlength: 200 },
    industryId: { type: ObjectId, ref: 'Industry', index: true },
    companyTypeId: { type: ObjectId, ref: 'CompanyType', index: true },
    email: { type: String, trim: true, lowercase: true, maxlength: 254 },
    phone: { type: String, trim: true, maxlength: 20 },
    website: { type: String, trim: true, maxlength: 2048 },
    address: { type: String, trim: true, maxlength: 500 },
    city: { type: String, trim: true, maxlength: 100 },
    state: { type: String, trim: true, maxlength: 100 },
    country: { type: String, trim: true, maxlength: 100 },
    postalCode: { type: String, trim: true, maxlength: 12 },
    gstNumber: { type: String, trim: true, uppercase: true, maxlength: 15, index: true },
    panNumber: { type: String, trim: true, uppercase: true, maxlength: 10 },
    // The user responsible for the account.
    assignedTo: { type: ObjectId, ref: 'User', index: true },
    // Which of our organizations owns the account.
    organizationId: { type: ObjectId, ref: 'Organization', index: true },
    status: {
      type: String,
      enum: Object.values(COMPANY_STATUS),
      default: COMPANY_STATUS.ACTIVE,
      index: true,
    },
    notes: { type: String, trim: true, maxlength: 5000 },
    createdBy: { type: ObjectId, ref: 'User' },
    // Soft delete: the record is kept so references from other records stay valid.
    deletedAt: { type: Date, default: null },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        industryId: 'industry',
        companyTypeId: 'companyType',
        organizationId: 'organization',
        assignedTo: 'assignedToUser',
        createdBy: 'createdByUser',
      },
    }),
  }
);

// Deleted companies are invisible to every read unless a query opts in with
// .setOptions({ withDeleted: true }).
function excludeDeleted() {
  if (!this.getOptions().withDeleted) this.where({ deletedAt: null });
}
companySchema.pre(/^find/, excludeDeleted);
companySchema.pre('countDocuments', excludeDeleted);

// Found by global search on these fields.
searchable(companySchema, ['companyCode', 'name', 'legalName', 'email', 'phone', 'gstNumber', 'panNumber', 'city']);

export default mongoose.model('Company', companySchema);
